import java.io.File;import java.security.MessageDigest;import java.util.HexFormat;import com.android.apksig.ApkVerifier;
class VerifyRelease{public static void main(String[] a)throws Exception{var r=new ApkVerifier.Builder(new File(a[0])).setMinCheckedPlatformVersion(29).setMaxCheckedPlatformVersion(35).build().verify();if(!r.isVerified()||!r.isVerifiedUsingV3Scheme()||r.getSignerCertificates().size()!=1)throw new IllegalStateException("APK signature invalid");String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(r.getSignerCertificates().get(0).getEncoded()));if(!sha.equals(a[1]))throw new IllegalStateException("Unexpected release certificate");System.out.println("verified=true\nv3=true\ncertificate_sha256="+sha);}}